lines=['# All non-CellScaffold repository snapshot','','Measured '+a['measured_at']+'. Read-only Git metadata and source comparison; not build or production acceptance.','','| Repository | Snapshot base | Local refs | Remote refs | Worktrees | Dirty primary paths | Stashes |','|---|---|---:|---:|---:|---:|---:|']
